def jsonb_get(data, path: str, default=None):
    """安全读取嵌套 JSON 字段。
    路径用点分隔（如 'a.b.c'）；任一层缺失或不是 dict 都返回 default。
    """
    paths = path.split('.')
    current = data
    for key in paths:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return default
    return current

# 测试用例
if __name__ == "__main__":
    data = {
        "a": {
            "b": {
                "c": 1
            }
        }
    }
    print(jsonb_get(data, "a.b.c"))  # 输出 1
    print(jsonb_get(data, "a.b.d", default="not found"))  # 输出 not found
    print(jsonb_get(data, "x.y.z", default="default value"))  # 输出 default value

